// Generates sw.js: the service worker with the list of app-shell files and a version
// that changes whenever any of them changes. The generated file is committed.
//
//   node scripts/build-sw.mjs      (also run by: npm run build:data)
//
// A unit test fails if sw.js is out of date, so a deploy cannot ship a stale cache list.
import { readFile, writeFile, readdir } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const ROOT = resolve(fileURLToPath(new URL('..', import.meta.url)));
export const SW_JS = join(ROOT, 'sw.js');

async function list(dir, ext) {
  const out = [];
  for (const entry of await readdir(join(ROOT, dir), { withFileTypes: true })) {
    const rel = `${dir}/${entry.name}`;
    if (entry.isDirectory()) out.push(...(await list(rel, ext)));
    else if (ext.some((e) => entry.name.endsWith(e))) out.push(rel);
  }
  return out;
}

/** Every file the app needs to open with no signal. */
export async function shellFiles() {
  const files = [
    'index.html',
    'manifest.webmanifest',
    ...(await list('css', ['.css'])),
    ...(await list('js', ['.js'])),
    ...(await list('icons', ['.png'])),
  ];
  return files.sort();
}

export async function renderServiceWorker() {
  const files = await shellFiles();
  const hash = createHash('sha256');
  for (const file of files) {
    hash.update(file);
    // Normalise line endings so the version is the same on Windows and on GitHub.
    const body = await readFile(join(ROOT, file));
    hash.update(file.endsWith('.png') ? body : body.toString('utf8').replace(/\r\n/g, '\n'));
  }
  const version = hash.digest('hex').slice(0, 12);
  return `// GENERATED by scripts/build-sw.mjs. Do not edit by hand.
// Caches the app shell so the site opens with no signal. A new deploy changes VERSION;
// the new worker installs in the background, takes over, and the page reloads itself once.
// It never touches localStorage, so the log is safe across updates.
const VERSION = '${version}';
const CACHE = \`ten-mile-shell-\${VERSION}\`;
const SHELL = ${JSON.stringify(['./', ...files], null, 2)};

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll(SHELL.map((url) => new Request(url, { cache: 'reload' }))))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('ten-mile-shell-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return; // the forecast goes straight to the network
  event.respondWith(
    caches.open(CACHE).then(async (cache) => {
      // Any page load gets the cached shell; ?date= and #routes are handled by the app.
      const key = request.mode === 'navigate' ? new URL('./', self.registration.scope).href : request;
      const hit = await cache.match(key, { ignoreSearch: true });
      return hit || fetch(request);
    }),
  );
});
`;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  await writeFile(SW_JS, await renderServiceWorker());
  console.log('Wrote sw.js');
}
